const spotHoldingPnlCurrencyFormatter: INumberFormatProps = {
  formatter: 'value',
  formatterOptions: {
    currency: '$',
  },
};

export type IPerpFillDirectionType =
  | 'openLong'
  | 'openShort'
  | 'closeLong'
  | 'closeShort'
  | 'unknown';

export const calcCellAlign = (align?: string) => {
  if (align === 'left') {
    return 'flex-start';
  }
  if (align === 'right') {
    return 'flex-end';
  }
  return 'center';
};

export const getColumnStyle = (column: IColumnConfig) => {
  const isFixedWidth = !!column.width;
  return {
    width: isFixedWidth ? column.width : undefined,
    minWidth: isFixedWidth ? undefined : column.minWidth,
    flexGrow: isFixedWidth ? undefined : column.flex || 1,
    flexBasis: isFixedWidth ? undefined : 0,
  };
};

export const getOrderAssetDisplayName = (
  coin: string,
  spotDisplayMap: Record<string, string>,
  spotPairDisplayNameMap: Record<string, string> = {},
) => {
  if (!isSpotInstrument(coin)) {
    return parseDexCoin(coin).displayName;
  }

  if (coin.includes('/')) {
    const [baseName, quoteName] = coin.split('/');
    return formatSpotPairDisplayName(baseName, quoteName);
  }

  return (
    spotPairDisplayNameMap[coin] ??
    spotDisplayMap[coin] ??
    getSpotTokenDisplayName(coin)
  );
};

export const getOrderSizeDisplayName = (
  coin: string,
  spotDisplayMap: Record<string, string>,
) => {
  if (!isSpotInstrument(coin)) {
    return parseDexCoin(coin).displayName;
  }

  if (coin.includes('/')) {
    const [baseName] = coin.split('/');
    return getSpotTokenDisplayName(baseName);
  }

  const displayName = spotDisplayMap[coin] ?? getSpotTokenDisplayName(coin);
  const [baseName] = displayName.split('/');
  return baseName;
};

export function normalizeEpochMs(timestamp: number | undefined) {
  if (!timestamp) {
    return undefined;
  }
  return timestamp > 1_000_000_000_000 ? timestamp : timestamp * 1000;
}

export function getTwapHistoryEventTimeMs(record: {
  time?: number;
  state: { timestamp: number };
}) {
  // Hyperliquid TWAP History displays the history record time, not the
  // TWAP state's start timestamp.
  return normalizeEpochMs(record.time) ?? record.state.timestamp;
}

export const getPerpFillDirectionType = (
  direction?: string,
): IPerpFillDirectionType => {
  const normalizedDirection = direction?.trim().toLowerCase() ?? '';

  // Reversals and liquidations contain "long" or "short" but are distinct fills.
  if (normalizedDirection === 'close long') {
    return 'closeLong';
  }

  if (normalizedDirection === 'close short') {
    return 'closeShort';
  }

  if (normalizedDirection === 'open long') {
    return 'openLong';
  }

  if (normalizedDirection === 'open short') {
    return 'openShort';
  }

  return 'unknown';
};

export const getFillDirectionDisplayInfo = ({
  fill,
  intl,
}: {
  fill: { coin: string; dir?: string; side: string };
  intl: IntlShape;
}) => {
  if (isSpotInstrument(fill.coin)) {
    return {
      text: intl.formatMessage({
        id:
          fill.side === 'B'
            ? ETranslations.global_buy
            : ETranslations.global_sell,
      }),
      color: fill.side === 'B' ? '$green11' : '$red11',
    };
  }

  let color = fill.side === 'B' ? '$green11' : '$red11';
  const directionType = getPerpFillDirectionType(fill.dir);
  let text = fill.dir ?? '';

  if (directionType === 'openLong') {
    text = intl.formatMessage({ id: ETranslations.perp_long });
  } else if (directionType === 'openShort') {
    text = intl.formatMessage({ id: ETranslations.perp_short });
  } else if (directionType === 'closeLong') {
    text = intl.formatMessage({ id: ETranslations.perp_order_close_long });
  } else if (directionType === 'closeShort') {
    text = intl.formatMessage({ id: ETranslations.perp_order_close_short });
  } else if (fill.dir?.trim().toLowerCase() === 'settlement') {
    text = intl.formatMessage({
      id: ETranslations.perp_trade_settlement__title,
    });
  }

  if (fill.side === 'A') {
    color = '$red11';
  }

  return { text, color };
};

export const isSpotHoldingStableCoin = isHyperliquidSpotStableCoin;

export const MIN_VISIBLE_SPOT_HOLDING_VALUE_USD = 5;

export type ISpotHoldingRawBalance = {
  coin: string;
  total: string;
  entryNtl?: string;
};

type ISpotUniversePriceSource = {
  name: string;
  baseName: string;
  quoteName: string;
};

type ISpotPriceContext = {
  markPx?: string;
};

export function buildSpotTokenPriceLookup({
  spotUniverses,
  priceMap,
}: {
  spotUniverses: ISpotUniversePriceSource[];
  priceMap: Record<string, ISpotPriceContext>;
}): Record<string, string> {
  const lookup: Record<string, string> = {};

  for (const universe of spotUniverses) {
    if (universe.quoteName === 'USDC') {
      const context = priceMap[universe.name];
      if (context?.markPx) {
        lookup[universe.baseName] = context.markPx;
      }
    }
  }

  for (const universe of spotUniverses) {
    if (!lookup[universe.baseName]) {
      const context = priceMap[universe.name];
      if (context?.markPx) {
        lookup[universe.baseName] = context.markPx;
      }
    }
  }

  return lookup;
}

export function getSpotHoldingValuation({
  rawCoin,
  total,
  entryNtl,
  midPrice,
}: {
  rawCoin: string;
  total: string;
  entryNtl?: string;
  midPrice?: string;
}) {
  const totalBN = new BigNumber(total);
  const entryNtlBN = new BigNumber(entryNtl || '0');
  const isStable = isSpotHoldingStableCoin(rawCoin);
  const hasPriceSource = isStable || Boolean(midPrice);

  let usdcValueBN: BigNumber;
  if (isStable) {
    usdcValueBN = totalBN;
  } else if (midPrice) {
    usdcValueBN = totalBN.multipliedBy(midPrice);
  } else {
    usdcValueBN = entryNtlBN;
  }

  return {
    totalBN,
    entryNtlBN,
    isStable,
    hasPriceSource,
    usdcValueBN,
  };
}

type ISpotHoldingFilterItem = {
  rawCoin: string;
  total: string;
  usdcValueNum: number;
  hasPriceSource: boolean;
};

export function isSpotHoldingVisible(
  balance: ISpotHoldingFilterItem,
  hideBelowThreshold: boolean,
): boolean {
  if (new BigNumber(balance.total).isZero()) {
    return false;
  }

  if (
    !hideBelowThreshold ||
    balance.rawCoin === 'USDC' ||
    !balance.hasPriceSource
  ) {
    return true;
  }

  return (
    !Number.isFinite(balance.usdcValueNum) ||
    balance.usdcValueNum >= MIN_VISIBLE_SPOT_HOLDING_VALUE_USD
  );
}

export function filterSpotHoldingBalances<T extends ISpotHoldingFilterItem>({
  balances,
  hideBelowThreshold,
}: {
  balances: T[];
  hideBelowThreshold: boolean;
}): T[] {
  return balances.filter((balance) =>
    isSpotHoldingVisible(balance, hideBelowThreshold),
  );
}

export function getVisibleSpotHoldingsCount({
  balances,
  tokenPriceLookup,
  hideBelowThreshold,
  hasPerpsUsdc,
}: {
  balances: ISpotHoldingRawBalance[];
  tokenPriceLookup: Record<string, string>;
  hideBelowThreshold: boolean;
  hasPerpsUsdc: boolean;
}): number {
  const visibleSpotBalances = filterSpotHoldingBalances({
    balances: balances.map((balance) => {
      const valuation = getSpotHoldingValuation({
        rawCoin: balance.coin,
        total: balance.total,
        entryNtl: balance.entryNtl,
        midPrice: tokenPriceLookup[balance.coin],
      });

      return {
        rawCoin: balance.coin,
        total: balance.total,
        usdcValueNum: valuation.usdcValueBN.toNumber(),
        hasPriceSource: valuation.hasPriceSource,
      };
    }),
    hideBelowThreshold,
  });
  const nonUsdcCount = visibleSpotBalances.filter(
    (balance) => balance.rawCoin !== 'USDC',
  ).length;
  const hasSpotUsdc = visibleSpotBalances.some(
    (balance) => balance.rawCoin === 'USDC',
  );

  return nonUsdcCount + (hasSpotUsdc || hasPerpsUsdc ? 1 : 0);
}

export const calculateSpotHoldingPnl = ({
  total,
  entryNtl,
  midPrice,
  isStable,
}: {
  total: string;
  entryNtl?: string;
  midPrice?: string;
  isStable: boolean;
}): {
  pnl?: string;
  pnlPercent?: number;
} => {
  const entryNtlBN = new BigNumber(entryNtl || '0');
  const pnl = calculateHyperliquidSpotHoldingPnl({
    total,
    entryNtl,
    priceUsd: midPrice,
    isStable,
  });

  if (!pnl || entryNtlBN.isZero() || !entryNtlBN.isFinite()) {
    return {};
  }

  const pnlBN = new BigNumber(pnl);
  return {
    pnl,
    pnlPercent: pnlBN.dividedBy(entryNtlBN).multipliedBy(100).toNumber(),
  };
};

export function canChasePerpsOrder(order: IPerpsFrontendOrder): boolean {
  const remainingSize = new BigNumber(order.sz);
  return Boolean(
    !isSpotInstrument(order.coin) &&
    getPerpsChaseOrderAmendKind(order) &&
    remainingSize.isFinite() &&
    remainingSize.gt(0),
  );
}

export function formatSpotHoldingPnlText(
  pnl?: string,
  pnlPercent?: number,
): string {
  if (!pnl) return '--';

  const pnlBN = new BigNumber(pnl);
  if (!pnlBN.isFinite() || pnlBN.isZero()) return '--';

  const sign = pnlBN.gt(0) ? '+' : '-';
  const formattedPnl = numberFormat(pnlBN.abs().toFixed(2), {
    ...spotHoldingPnlCurrencyFormatter,
  });
  const formattedPnlPercent = new BigNumber(pnlPercent ?? 0).abs().toFixed(1);

  return `${sign}${formattedPnl} (${sign}${formattedPnlPercent}%)`;
}
